shader_type spatial;
render_mode cull_front, unshaded;

uniform vec4 outline_color : source_color = vec4(0.0, 1.0, 1.0, 1.0);
uniform float outline_thickness : hint_range(1.0, 1.5, 0.005) = 1.05;
uniform float emission_energy : hint_range(0.0, 16.0, 0.1) = 3.0;

void vertex() {
	VERTEX *= outline_thickness;
}

void fragment() {
	ALBEDO = outline_color.rgb;
	EMISSION = outline_color.rgb * emission_energy;
}

extends Node3D

@export var cube_scene: PackedScene
@export var cube_container: Node3D
@export var cube_root: Node3D

func _ready():
	for x in range(-1, 2):
		for y in range(-1, 2):
			for z in range(-1, 2):
				if x == 0 and y == 0 and z == 0:
					continue
				var cubie = cube_scene.instantiate()
				cubie.position = Vector3(x, y, z)
				cubie.add_to_group('cubies')
				cube_root.add_child(cubie)

func _unhandled_input(event):
	if is_scrambling:
		return
	if event is InputEventScreenTouch:
		if event.pressed:
			touch_start_pos = event.position
			is_dragging = false
		else:
			if not is_dragging:
				pass
			else:
				is_dragging = false
	elif event is InputEventScreenDrag:
		if not is_dragging:
			if event.position.distance_to(touch_start_pos) > drag_threshold:
				is_dragging = true
		if is_dragging:
			_rotate_cube(event.relative)

func _rotate_cube(drag_motion: Vector2):
	if cube_container == null:
		return
	cube_container.rotate_y(drag_motion.x * sensitivity)
	var new_x = cube_container.rotation.x - (-drag_motion.y * sensitivity)
	cube_container.rotation.x = clamp(new_x, deg_to_rad(-80), deg_to_rad(80))
	velocity_y = -drag_motion.x * sensitivity
	velocity_x = -drag_motion.y * sensitivity

func _process(delta):
	if not is_dragging and (velocity_y != 0.0 or velocity_x != 0.0):
		cube_container.rotate_y(velocity_y)
		var new_x = cube_container.rotation.x + velocity_x
		cube_container.rotation.x = clamp(new_x, deg_to_rad(-80), deg_to_rad(80))
		velocity_y = lerp(velocity_y, 0.0, 10.0 * delta)
		velocity_x = lerp(velocity_x, 0.0, 10.0 * delta)
		if abs(velocity_y) < 0.001:
			velocity_y = 0.0
		if abs(velocity_x) < 0.001:
			velocity_x = 0.0
